#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for (int i = 0; i < (int)(n); ++i)
#define push_back pb
#define emplace_back eb
#define first fi
#define second se
typedef long long ll;
typedef vector<int> vi;
typedef pair<int, int> pii;
typedef long double ld;

const int MAX_M = 21;
const ld EPS = 1e-6;

int total = 0, selected_k, total_m;
ld probabilities[MAX_M];
int indices[MAX_M];
ld dynamic[1 << MAX_M];
ld result[MAX_M];

void read_input() {
    cin >> total_m >> selected_k;
    for (int i = 0; i < total_m; ++i) {
        ld val;
        cin >> val;
        if (val > EPS) {
            probabilities[total] = val;
            indices[total] = i;
            ++total;
        } else {
            result[i] = 0;
        }
    }
}

void process() {
    if (selected_k >= total) {
        for (int i = 0; i < total; ++i)
            result[indices[i]] = 1.0;
    } else {
        dynamic[0] = 1.0;
        for (int mask = 0; mask < (1 << total); ++mask) {
            if (__builtin_popcount(mask) < selected_k) {
                ld sum_probs = 0.0;
                for (int t = 0; t < total; ++t)
                    if (!((mask >> t) & 1))
                        sum_probs += probabilities[t];
                for (int t = 0; t < total; ++t)
                    if (!((mask >> t) & 1))
                        dynamic[mask ^ (1 << t)] += probabilities[t] / sum_probs * dynamic[mask];
            }
        }
        for (int mask = 0; mask < (1 << total); ++mask) {
            if (__builtin_popcount(mask) == selected_k) {
                for (int t = 0; t < total; ++t)
                    if ((mask >> t) & 1)
                        result[indices[t]] += dynamic[mask];
            }
        }
    }
    for (int i = 0; i < total_m; ++i)
        cout << result[i] << " ";
    cout << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);
    cout << fixed;
    read_input();
    process();
    return 0;
}
